import { formatDurationMs } from "@ai-matrx/kit/format";
const SHORT_TEXT_FOLD_MAX = 400;
const AGENT_WORK_MIN_ITEMS = 2;
function foldAgentWork(items, { classify, stepsOf, spanOf }) {
  const out = [];
  for (let i = 0; i < items.length; ) {
    const cls = classify(items[i]);
    if (cls === "visible") {
      out.push(items[i]);
      i++;
      continue;
    }
    let j = i;
    while (j < items.length && classify(items[j]) !== "visible") j++;
    let run = items.slice(i, j);
    let lo = 0;
    let hi = run.length;
    while (lo < hi && classify(run[lo]) === "shortText") lo++;
    while (hi > lo && classify(run[hi - 1]) === "shortText") hi--;
    const leading = run.slice(0, lo);
    const trailing = run.slice(hi);
    run = run.slice(lo, hi);
    out.push(...leading);
    const hasWork = run.some((item) => classify(item) === "work");
    if (run.length >= AGENT_WORK_MIN_ITEMS && hasWork) {
      let stepCount = 0;
      let start = Infinity;
      let end = -Infinity;
      let firstTimed = -1;
      let lastTimed = -1;
      run.forEach((item, index) => {
        stepCount += Math.max(1, stepsOf(item));
        const span = spanOf(item);
        if (span) {
          if (span.start < start) start = span.start;
          if (span.end > end) end = span.end;
          if (firstTimed < 0) firstTimed = index;
          lastTimed = index;
        }
      });
      const untimedOutside = run.some(
        (item, index) => classify(item) === "work" && spanOf(item) === null && (index < firstTimed || index > lastTimed)
      );
      out.push({
        kind: "agent_work",
        items: run,
        stepCount,
        durationMs: end > start && !untimedOutside ? Math.round(end - start) : null
      });
    } else {
      out.push(...run);
    }
    out.push(...trailing);
    i = j;
  }
  return out;
}
function formatWorkDuration(durationMs) {
  return formatDurationMs(durationMs, { style: "compact" });
}
export {
  AGENT_WORK_MIN_ITEMS,
  SHORT_TEXT_FOLD_MAX,
  foldAgentWork,
  formatWorkDuration
};
